code:
// ======================================================================
// FVTT V13 综合世界脚本 (D&D 5.x)
// 包含：冒险者履历、CSS滤镜接收、21点、拼酒大赛、赛马比赛、全局宏Toggle、骰控(socketlib)
// 本版改动：骰控由裸 game.socket 迁移到 socketlib（与酒馆小游戏同一条已验证信道）
// ======================================================================

// ==========================================
// 模块 1：冒险者履历核心 UI 函数 (直接挂载到 Window，无需等待钩子)
// ==========================================
window.renderAdventurerLogApp = async function(targetActor) {
    if (!targetActor) return;

    // 自动打开对应冒险者的角色卡面板，方便拖拽物品
    if (targetActor.sheet) {
        targetActor.sheet.render(true);
    }

    const FLAG_SCOPE = "world";
    const FLAG_KEY = "adventurer_log_data";
    const COLOR_KEY = "adventurer_log_theme";
    const GP_KEY = "adventurer_log_last_gp";

    const THEMES = [
        { name: "经典羊皮纸", bg: "#fdf6e3", txt: "#2c3e50", accent: "#5d4037", box: "rgba(255,255,255,0.6)", hint: "#666" },
        { name: "暗夜黑", bg: "#1e1e1e", txt: "#e0e0e0", accent: "#7a7a7a", box: "rgba(255,255,255,0.08)", hint: "#aaa" },
        { name: "深渊蓝", bg: "#15202b", txt: "#d1d8e0", accent: "#4a6984", box: "rgba(0,0,0,0.3)", hint: "#8a9ea8" },
        { name: "猩红血契", bg: "#2c0e0e", txt: "#e8d5d5", accent: "#a34545", box: "rgba(0,0,0,0.4)", hint: "#b39494" }
    ];

    function escapeRegExp(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    Object.values(ui.windows).forEach(w => {
        if (w.title === `冒险者履历 - ${targetActor.name}`) w.close();
    });

    let logs = targetActor.getFlag(FLAG_SCOPE, FLAG_KEY) || [];
    let themeIdx = targetActor.getFlag(FLAG_SCOPE, COLOR_KEY) || 0;
    if (themeIdx >= THEMES.length) themeIdx = 0;
    let t = THEMES[themeIdx];
    
    let currentGp = targetActor.system?.currency?.gp || 0;
    let lastGp = targetActor.getFlag(FLAG_SCOPE, GP_KEY);
    if (lastGp === undefined) {
        lastGp = currentGp;
        await targetActor.setFlag(FLAG_SCOPE, GP_KEY, currentGp);
    }
    let gpDiff = currentGp - lastGp;

    let logsByDate = {};
    logs.forEach(l => {
        if (!logsByDate[l.date]) logsByDate[l.date] = [];
        logsByDate[l.date].push(l);
    });

    let orderedDates = [...new Set(logs.map(l => l.date))].reverse();

    let logHtml = "";
    if (orderedDates.length === 0) {
        logHtml = `<div id="emptyLog" style="height: 100%; display: flex; align-items: center; justify-content: center; color: var(--hint); font-style: italic;">暂无记录。请在左侧手动录入，或直接拖拽物品进虚线框。</div>`;
    } else {
        orderedDates.forEach(date => {
            logHtml += `<div class="date-group" data-date="${date}">`;
            logHtml += `<div class="date-header">📅 ${date}</div>`;
            
            let dailyLogs = [...logsByDate[date]].reverse();
            
            dailyLogs.forEach(l => {
                let icon = "", prefix = "", bdColor = "";
                if (l.type === "levelup") { icon = "🌟"; prefix = "获得特性/法术："; bdColor = "#f5b041"; }
                else if (l.type === "loot") { icon = "🎁"; prefix = "拾取神兵/道具："; bdColor = "#5dade2"; }
                else if (l.type === "boon") { icon = "✨"; prefix = "获得赐福/专长："; bdColor = "#af7ac5"; }
                else if (l.type === "gold") { icon = "💰"; prefix = "财务变动："; bdColor = "#f1c40f"; }
                else { icon = "📜"; prefix = "经历大事件："; bdColor = "#aeb6bf"; }
                
                let searchText = (prefix + l.desc + " " + date).toLowerCase();

                logHtml += `
                <div class="log-entry" data-type="${l.type}" data-text="${searchText}" style="border-left: 5px solid ${bdColor};">
                    <span style="font-size: 1.2em; margin-right: 8px;">${icon}</span>
                    <div style="flex: 1; font-size: 14.5px; line-height: 1.5; color: var(--txt);">
                        <b style="color: ${bdColor}; filter: saturate(1.5);">${prefix}</b> ${l.desc}
                    </div>
                </div>`;
            });
            logHtml += `</div>`; 
        });
    }

    const today = new Date().toLocaleDateString('zh-CN');

    let diffHtml = "";
    if (gpDiff !== 0) {
        let color = gpDiff > 0 ? "#2ecc71" : "#e74c3c";
        let sign = gpDiff > 0 ? "+" : "";
        diffHtml = `<button id="btnSyncGp" style="flex:1; margin-left:10px; background:var(--box); color:var(--txt); border:1px solid var(--accent); border-radius:4px; cursor:pointer;">一键结算差额 (<span style="color:${color}; font-weight:bold;">${sign}${gpDiff} GP</span>)</button>`;
    } else {
        diffHtml = `<span style="flex:1; margin-left:10px; color:var(--hint); font-size:12px; text-align:right;">无资金变动</span>`;
    }

    const dialogHtml = `
    <style>
        .log-container {
            --bg: ${t.bg}; --txt: ${t.txt}; --accent: ${t.accent}; --box: ${t.box}; --hint: ${t.hint};
            display: flex; gap: 20px; height: 600px; background: var(--bg); color: var(--txt); padding: 15px; font-family: "Segoe UI", sans-serif; transition: background 0.3s, color 0.3s;
        }
        .log-form { flex: 1; border-right: 2px dashed var(--accent); padding-right: 20px; display: flex; flex-direction: column; gap: 12px; }
        .log-history { flex: 1.5; padding-left: 5px; padding-right: 5px; background: var(--box); border-radius: 8px; display: flex; flex-direction: column; }
        .log-list-wrapper { flex: 1; overflow-y: auto; padding-right: 8px; }
        .log-list-wrapper::-webkit-scrollbar { width: 6px; }
        .log-list-wrapper::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 3px; }
        
        .neat-input { width: 100%; height: 35px; border: 1px solid var(--accent); border-radius: 4px; padding: 0 10px; box-sizing: border-box; font-size: 14px; background: var(--bg); color: var(--txt); }
        .neat-input option { background: var(--bg); color: var(--txt); }
        .neat-textarea { width: 100%; flex: 1; border: 1px solid var(--accent); border-radius: 4px; padding: 10px; box-sizing: border-box; resize: none; font-family: inherit; font-size: 14.5px; line-height: 1.5; background: var(--bg); color: var(--txt); }
        
        .drop-zone { border: 2px dashed var(--accent); background: var(--box); padding: 25px 15px; text-align: center; border-radius: 8px; color: var(--accent); font-weight: bold; transition: all 0.2s ease; cursor: pointer; display: flex; flex-direction: column; align-items: center; justify-content: center; }
        .drop-zone.dragover { background: var(--accent); color: var(--bg); transform: scale(1.02); }
        .drop-zone span { color: var(--hint); }
        .drop-zone.dragover span { color: var(--bg); }
        .filter-bar { display: flex; gap: 10px; margin-bottom: 12px; flex-shrink: 0; }
        .date-header { display: inline-block; background: var(--accent); color: var(--bg); padding: 4px 12px; border-radius: 4px; font-weight: bold; margin-top: 15px; margin-bottom: 8px; font-size: 13px; box-shadow: 1px 1px 3px rgba(0,0,0,0.2); }
        .date-group:first-child .date-header { margin-top: 5px; }
        .log-entry { background: var(--box); padding: 10px 12px; margin-bottom: 8px; border-radius: 0 6px 6px 0; box-shadow: 1px 1px 4px rgba(0,0,0,0.08); display: flex; align-items: flex-start; }
        .header-wrap { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid var(--accent); margin:0 0 5px 0; padding-bottom:5px; color: var(--accent); }
        .theme-btn { cursor: pointer; font-size: 1.2em; transition: transform 0.2s; }
        .theme-btn:hover { transform: scale(1.2); }
    </style>
    <div class="log-container" id="mainContainer">
        <div class="log-form">
            <div class="header-wrap">
                <h2 style="margin:0; color:var(--accent);"><i class="fas fa-feather-alt"></i> 新增历程</h2>
                <i class="fas fa-palette theme-btn" id="themeToggleBtn" title="切换显示主题"></i>
            </div>
            
            <div style="background: var(--box); padding: 8px 12px; border-radius: 4px; display: flex; align-items: center; justify-content: space-between; margin-top: 5px;">
                <span style="font-size:13px; color:var(--txt);">当前金币: <b>${currentGp}</b></span>
                ${diffHtml}
            </div>
            
            <div>
                <label style="font-weight: bold; font-size: 13px; color: var(--txt);">发生时间 (支持自定义):</label>
                <input type="text" id="logDate" class="neat-input" style="margin-top:5px;" value="${today}">
            </div>
            
            <div id="itemDropZone" class="drop-zone">
                <i class="fas fa-box-open" style="font-size: 2em; margin-bottom: 10px;"></i>
                <span style="font-size: 1.1em; color:inherit;">将 物品/法术/特性 拖拽至此</span>
                <span style="font-size: 0.85em; font-weight: normal; margin-top: 5px;">自动识别归类并合并数量</span>
            </div>

            <div style="margin-top: 10px;">
                <label style="font-weight: bold; font-size: 13px; color: var(--txt);">手动记录分类:</label>
                <select id="logType" class="neat-input" style="margin-top:5px; margin-bottom:8px;">
                    <option value="story">📜 经历大事件 (剧情/里程碑)</option>
                    <option value="levelup">🌟 获得特性/法术 (职业/升级获得)</option>
                    <option value="loot">🎁 拾取神兵/道具 (装备/战利品)</option>
                    <option value="boon">✨ 获得赐福/专长 (额外增益/Feat)</option>
                </select>
            </div>
            <div style="display:flex; flex-direction:column; flex:1;">
                <textarea id="logDesc" class="neat-textarea" placeholder="手动输入事件说明..."></textarea>
            </div>
        </div>

        <div class="log-history">
            <h2 style="border-bottom: 2px solid var(--accent); margin:0 0 10px 0; padding-bottom:5px; color:var(--accent); flex-shrink: 0;"><i class="fas fa-book"></i> 档案总览</h2>
            
            <div class="filter-bar">
                <select id="filterType" class="neat-input" style="flex: 1; height: 32px; font-weight: bold;">
                    <option value="all">🔍 查阅全部记录</option>
                    <option value="levelup">🌟 仅看 特性/法术</option>
                    <option value="loot">🎁 仅看 神兵/道具</option>
                    <option value="boon">✨ 仅看 赐福/专长</option>
                    <option value="story">📜 仅看 大事件</option>
                    <option value="gold">💰 仅看 财务变动</option>
                </select>
                <input type="text" id="searchInput" class="neat-input" placeholder="关键词检索..." style="flex: 1.5; height: 32px;">
            </div>

            <div class="log-list-wrapper">
                ${logHtml}
            </div>
        </div>
    </div>
    `;

    let appDialog = new Dialog({
        title: `冒险者履历 - ${targetActor.name}`,
        content: dialogHtml,
        render: (html) => {
            html.find("#themeToggleBtn").on("click", async () => {
                themeIdx = (themeIdx + 1) % THEMES.length;
                let nt = THEMES[themeIdx];
                let cont = html.find("#mainContainer")[0];
                cont.style.setProperty("--bg", nt.bg);
                cont.style.setProperty("--txt", nt.txt);
                cont.style.setProperty("--accent", nt.accent);
                cont.style.setProperty("--box", nt.box);
                cont.style.setProperty("--hint", nt.hint);
                await targetActor.setFlag(FLAG_SCOPE, COLOR_KEY, themeIdx);
            });

            html.find("#btnSyncGp").on("click", async () => {
                let dateVal = html.find("#logDate").val();
                let currentLogs = targetActor.getFlag(FLAG_SCOPE, FLAG_KEY) || [];
                let sign = gpDiff > 0 ? "+" : "";
                
                currentLogs.push({
                    id: foundry.utils.randomID(),
                    type: "gold",
                    date: dateVal,
                    desc: `结余记录：${sign}${gpDiff} GP (当前总额: ${currentGp} GP)`
                });

                await targetActor.setFlag(FLAG_SCOPE, FLAG_KEY, currentLogs);
                await targetActor.setFlag(FLAG_SCOPE, GP_KEY, currentGp);
                appDialog.close();
                window.renderAdventurerLogApp(targetActor); 
            });

            const filterLogs = () => {
                let filterType = html.find("#filterType").val();
                let searchTxt = html.find("#searchInput").val().toLowerCase();
                
                html.find(".date-group").each(function() {
                    let hasVisible = false;
                    $(this).find(".log-entry").each(function() {
                        let entryType = $(this).data("type");
                        let entryText = $(this).data("text");
                        let matchType = (filterType === "all" || filterType === entryType);
                        let matchSearch = (searchTxt === "" || entryText.includes(searchTxt));
                        
                        if (matchType && matchSearch) {
                            $(this).show();
                            hasVisible = true;
                        } else {
                            $(this).hide();
                        }
                    });
                    $(this).toggle(hasVisible);
                });
            };
            html.find("#filterType").on("change", filterLogs);
            html.find("#searchInput").on("input", filterLogs);

            const dropZone = html.find("#itemDropZone");
            dropZone.on("dragover", (e) => { e.preventDefault(); dropZone.addClass("dragover"); });
            dropZone.on("dragleave", (e) => { e.preventDefault(); dropZone.removeClass("dragover"); });
            dropZone.on("drop", async (e) => {
                e.preventDefault();
                dropZone.removeClass("dragover");
                
                try {
                    let data = JSON.parse(e.originalEvent.dataTransfer.getData("text/plain"));
                    if (!data.uuid) return;
                    let doc = await fromUuid(data.uuid);
                    if (!doc) return;

                    let newCategory = "story";
                    let isPhysicalItem = ["weapon", "equipment", "consumable", "tool", "loot", "backpack"].includes(doc.type);
                    
                    if (doc.type === "spell" || doc.type === "class" || doc.type === "subclass") {
                        newCategory = "levelup"; 
                    } else if (doc.type === "feat") {
                        if (doc.system?.type?.value === "feat") newCategory = "boon"; 
                        else newCategory = "levelup"; 
                    } else {
                        newCategory = "loot"; 
                    }
                    
                    let finalQty = 1;
                    if (isPhysicalItem) {
                        let sysQty = doc.system?.quantity || 1;
                        finalQty = await new Promise((resolve) => {
                            new Dialog({
                                title: "录入数量",
                                content: `<div style="padding:10px 5px; font-size:14px;"><p>正在录入：<b>${doc.name}</b></p><div style="display:flex; gap:10px;"><label>获得数量:</label><input type="number" id="dropQty" value="${sysQty}" min="1" style="flex:1;"></div></div>`,
                                buttons: {
                                    ok: { icon: '<i class="fas fa-check"></i>', label: "确认", callback: (h) => resolve(parseInt(h.find("#dropQty").val()) || 1) },
                                    cancel: { icon: '<i class="fas fa-times"></i>', label: "取消", callback: () => resolve(null) }
                                },
                                default: "ok"
                            }).render(true);
                        });
                        if (finalQty === null) return;
                    }

                    let dateVal = html.find("#logDate").val();
                    let currentLogs = targetActor.getFlag(FLAG_SCOPE, FLAG_KEY) || [];
                    
                    let merged = false;
                    let safeName = escapeRegExp(doc.name);
                    let regex = new RegExp(`^${safeName}(?: x(\\d+))?$`);
                    
                    for (let i = currentLogs.length - 1; i >= 0; i--) {
                        let l = currentLogs[i];
                        if (l.date === dateVal && l.type === newCategory) {
                            let match = l.desc.match(regex);
                            if (match) {
                                let oldQty = match[1] ? parseInt(match[1]) : 1;
                                l.desc = `${doc.name} x${oldQty + finalQty}`;
                                merged = true;
                                break;
                            }
                        }
                    }
                    
                    if (!merged) {
                        let descVal = doc.name + (finalQty > 1 ? ` x${finalQty}` : "");
                        currentLogs.push({
                            id: foundry.utils.randomID(),
                            type: newCategory,
                            date: dateVal,
                            desc: descVal
                        });
                    }

                    await targetActor.setFlag(FLAG_SCOPE, FLAG_KEY, currentLogs);
                    appDialog.close();
                    window.renderAdventurerLogApp(targetActor); 

                } catch (err) {
                    ui.notifications.warn("不支持的数据格式。");
                }
            });
        },
        buttons: {
            add: {
                icon: '<i class="fas fa-save"></i>',
                label: "保存",
                callback: async (html) => {
                    let typeVal = html.find("#logType").val();
                    let dateVal = html.find("#logDate").val();
                    let descVal = html.find("#logDesc").val().trim();

                    if (!descVal) return ui.notifications.warn("文本框为空。");

                    let currentLogs = targetActor.getFlag(FLAG_SCOPE, FLAG_KEY) || [];
                    currentLogs.push({
                        id: foundry.utils.randomID(),
                        type: typeVal,
                        date: dateVal,
                        desc: descVal.replace(/\n/g, "<br>")
                    });

                    await targetActor.setFlag(FLAG_SCOPE, FLAG_KEY, currentLogs);
                    window.renderAdventurerLogApp(targetActor); 
                }
            },
            undo: {
                icon: '<i class="fas fa-trash-alt"></i>',
                label: "删除末条",
                callback: async () => {
                    let currentLogs = targetActor.getFlag(FLAG_SCOPE, FLAG_KEY) || [];
                    if (currentLogs.length > 0) {
                        currentLogs.pop(); 
                        await targetActor.setFlag(FLAG_SCOPE, FLAG_KEY, currentLogs);
                        window.renderAdventurerLogApp(targetActor);
                    }
                }
            },
            cancel: { icon: '<i class="fas fa-times"></i>', label: "关闭" }
        },
        default: "add"
    }, { width: 950 });
    
    appDialog.render(true);
};

// 模块 2：环境滤镜接收器 (独立运行)
// ==========================================
if (!globalThis.cssFilterHookRegistered) {
    globalThis.drawLocalCssFilter = function(filterData) {
        document.getElementById("macro-css-filter")?.remove();
        if (!filterData || filterData.color === "none") return;
        
        let filterDiv = document.createElement("div");
        filterDiv.id = "macro-css-filter";
        filterDiv.style.cssText = `position:fixed; top:0; left:0; width:100vw; height:100vh; pointer-events:none; background-color:${filterData.color}; mix-blend-mode:multiply; z-index: 10; transition: background-color 1s;`;
        
        let uiMiddle = document.getElementById("ui-middle");
        if (uiMiddle && uiMiddle.parentNode) {
            uiMiddle.parentNode.insertBefore(filterDiv, uiMiddle);
        } else {
            document.body.appendChild(filterDiv);
        }
    };

    Hooks.on("updateScene", (scene, data, options, userId) => {
    if (scene.id !== canvas.scene.id) return;
    if (foundry.utils.hasProperty(data, "flags.world.cssFilter")) {
        globalThis.drawLocalCssFilter(foundry.utils.getProperty(data, "flags.world.cssFilter"));
    }
});

    Hooks.on("canvasReady", () => {
        globalThis.drawLocalCssFilter(canvas.scene.getFlag("world", "cssFilter"));
    });

    globalThis.cssFilterHookRegistered = true;
    console.log("🟢 环境滤镜接收器已启动！");
}

if (canvas && canvas.scene) {
    globalThis.drawLocalCssFilter(canvas.scene.getFlag("world", "cssFilter"));
}

// 核心模块：统一加载器 (彻底解决时序/钩子丢失问题)
// 将所有需要在游戏加载完成后执行的注入、Socket、重写放在这里
// ==========================================
function initializeWorldScripts() {
    
    console.log("🛠️ 正在统一部署 World Scripts...");

    // -------------------------
    // [1] 冒险者履历 - UI注入
    // -------------------------
    if (!globalThis.hasAdventurerLogHook) {
        Hooks.on("dnd5e.restCompleted", (actor, data) => {
            if (data.longRest && actor.isOwner) {
                if (!game.user.isGM && game.user.character?.id !== actor.id) return;
                if (window.renderAdventurerLogApp) window.renderAdventurerLogApp(actor);
            }
        });
        globalThis.hasAdventurerLogHook = true;
    }

    if (!globalThis.advLogUIPoller) {
        globalThis.advLogUIPoller = setInterval(() => {
            let $targetBtn = $('button.control.ui-control.layer.icon.fa-solid.fa-bookmark');
            if ($targetBtn.length > 0 && $('#adv-log-sidebar-btn').length === 0) {
                let btn = $(`<button id="adv-log-sidebar-btn" class="control ui-control layer icon fa-solid fa-book" title="打开冒险履历" style="color: #ffc107; margin-top: 5px;"></button>`);
                btn.on('click', () => {
                    let actor = canvas.tokens.controlled[0]?.actor || game.user.character;
                    if(actor) {
                        window.renderAdventurerLogApp(actor);
                    } else {
                        ui.notifications.warn("请先选中一个代币，或在左下角绑定玩家角色！");
                    }
                });
                btn.insertAfter($targetBtn);
            }
        }, 1500); 
    }

    // -------------------------
    // [2] 全局宏 Toggle (面板开/关切换) 补丁
    // -------------------------
    if (!globalThis.advMacroToggleInjected) {
        globalThis.macroAppTracker = new Map();
        const originalMacroExecute = Macro.prototype.execute;

        Macro.prototype.execute = async function(context, args) {
            const macroId = this.id;
            const associatedWindowKey = globalThis.macroAppTracker.get(macroId);
            
            if (associatedWindowKey !== undefined) {
                const activeApp = ui.windows[associatedWindowKey];
                if (activeApp && activeApp.rendered) {
                    await activeApp.close();
                    globalThis.macroAppTracker.delete(macroId);
                    return; 
                } else {
                    globalThis.macroAppTracker.delete(macroId);
                }
            }

            globalThis._executingMacroId = macroId;
            let result;
            try {
                result = await originalMacroExecute.apply(this, [context, args]);
            } catch(e) { console.error("宏执行报错:", e); }

            setTimeout(() => {
                if (globalThis._executingMacroId === macroId) globalThis._executingMacroId = null;
            }, 500);
            return result;
        };

        Hooks.on("renderApplication", (app, html, data) => {
            if (globalThis._executingMacroId) {
                if (app instanceof Dialog || !app.options.id || app.options.id.startsWith("dialog")) {
                    globalThis.macroAppTracker.set(globalThis._executingMacroId, app.appId);
                }
            }
        });

        Hooks.on("renderApplicationV2", (app, html, data) => {
             if (globalThis._executingMacroId) {
                 globalThis.macroAppTracker.set(globalThis._executingMacroId, app.id);
             }
        });
        globalThis.advMacroToggleInjected = true;
        console.log("🟢 屏幕面板宏 Toggle 补丁已注入");
    }

    // -------------------------
    // [3] Socketlib 服务端与客户端通信注册 (21点、拼酒、赛马、骰控)
    // -------------------------
    if (game.modules.get("socketlib")?.active) {
        const socketId = game.system.id; 
        let socket = socketlib.modules.get(socketId) || socketlib.registerSystem(socketId);

        // 🃏 21点玩家端 UI 监听器
        socket.register("promptTavern21ProUI", async (data) => {
            return new Promise((resolve) => {
                let { dice, knownIndices, hasCheated } = data;
                let diceHtml = dice.map((d, i) => {
                    let isKnown = knownIndices.includes(i);
                    let val = isKnown ? d : "?";
                    let bgColor = isKnown ? "#fff" : "#333";
                    let textColor = isKnown ? "#8b0000" : "#fff";
                    let borderColor = isKnown ? "#8b0000" : "#000";
                    return `<span style="display:inline-block; width:30px; height:30px; border:2px solid ${borderColor}; border-radius:5px; text-align:center; line-height:30px; font-weight:bold; background:${bgColor}; color:${textColor}; font-size:18px; margin: 2px; box-shadow: 1px 1px 3px rgba(0,0,0,0.4);">${val}</span>`;
                }).join("");

                let cheatBtnHtml = !hasCheated ? `
                    <hr style="border: 0; height: 1px; background: #ddd; margin: 15px 0;">
                    <div style="text-align: center;">
                        <button id="btn-cheat-trigger" style="background: #ffebee; border: 1px solid #c62828; color: #c62828; padding: 5px 10px; cursor: pointer;">
                            <i class="fas fa-mask"></i> 尝试出千
                        </button>
                    </div>` : "";

                let dialogInstance = new Dialog({
                    title: "🃏 21点 - 轮到你了！",
                    content: `<div style="text-align: center; margin-bottom: 15px;"><h3>当前手牌</h3><div style="margin: 10px 0; display: flex; justify-content: center;">${diceHtml}</div>${cheatBtnHtml}</div>`,
                    buttons: {
                        hit: { icon: '<i class="fas fa-plus"></i>', label: "加牌", callback: () => resolve({ action: "hit" }) },
                        stand: { icon: '<i class="fas fa-hand-paper"></i>', label: "停牌", callback: () => resolve({ action: "stand" }) }
                    },
                    default: "stand",
                    close: () => resolve({ action: "stand" }), 
                    render: (html) => {
                        html.find('#btn-cheat-trigger').click((ev) => {
                            ev.preventDefault();
                            let cheatOptions = dice.map((d, i) => `<option value="${i}">第 ${i+1} 颗 (${i===0?"明牌":"暗牌"})</option>`).join("");
                            new Dialog({
                                title: "🎩 偷天换日",
                                content: `<div><label>目标骰子:</label><select id="cheat-idx">${cheatOptions}</select></div><div style="margin-top:10px;"><label>修改为(1-6):</label><input type="number" id="cheat-val" min="1" max="6" value="6"></div>`,
                                buttons: {
                                    ok: {
                                        icon: '<i class="fas fa-check"></i>', label: "确认",
                                        callback: (chtml) => {
                                            dialogInstance.close();
                                            resolve({ action: "cheat", targetIndex: Number(chtml.find('#cheat-idx').val()), newValue: Number(chtml.find('#cheat-val').val()) });
                                        }
                                    },
                                    cancel: { icon: '<i class="fas fa-times"></i>', label: "取消" }
                                }
                            }).render(true);
                        });
                    }
                });
                dialogInstance.render(true);
            });
        });
        console.log("🟢 21点监听器已加载");

       socket.register("requestNativeSave", async (data) => {
            let actor = game.actors.get(data.actorId);
            if (!actor) return 0;
            ui.notifications.info(`🍻 轮到你了！请进行体质豁免 (DC ${data.dc})，10 秒未掷将自动掷骰。`);

            // 自动掷骰（不弹框，直接 Roll）
            const autoTotal = async () => {
                const conMod = actor.system?.abilities?.con?.mod ?? 0;
                const r = await new Roll(`1d20 + ${conMod}`).evaluate();
                return r.total;
            };

            let timer;
            const timeoutPromise = new Promise((resolve) => {
                timer = setTimeout(async () => {
                    // 关闭可能残留的掷骰弹窗
                    for (const w of Object.values(ui.windows)) {
                        try {
                            if ((w.title || "").includes("豁免") || (w.title || "").includes("Saving")) w.close();
                        } catch (_) {}
                    }
                    resolve(await autoTotal());
                }, 10000);
            });

            const manualPromise = (async () => {
                let roll = null;
                try {
                    if (typeof actor.rollSavingThrow === "function") roll = await actor.rollSavingThrow({ ability: "con" });
                    else if (typeof actor.rollAbilitySave === "function") roll = await actor.rollAbilitySave("con");
                    else return null;
                } catch (e) { return null; }
                if (!roll) return null;
                return Array.isArray(roll) ? roll[0].total : roll.total;
            })();

            try {
                const r = await Promise.race([manualPromise, timeoutPromise]);
                return r === null ? await autoTotal() : r;
            } finally {
                clearTimeout(timer);
            }
        });
        console.log("🟢 拼酒大赛监听器已加载（10秒超时自动掷）");

        // 🐎 赛马面板弹出
        socket.register("openHorseRaceApp", () => {
            const activeApp = Object.values(ui.windows).find(w => w.id === "horse-race-v1");
            if (activeApp) activeApp.render(true, {focus: true});
            // 依赖全局的类，在赛马宏运行前保证有效，由于代码量太大，具体赛马的类保留在原发出的宏里
            else if (typeof HorseRaceApp !== "undefined") new HorseRaceApp().render(true); 
            else ui.notifications.error("未找到赛马环境数据，请确保 GM 先运行了赛马宏！");
        });
        console.log("🟢 赛马监听器已加载");

        // 🎲 骰控核心 (socketlib + 分骰面) —— V13 正确钩子：mapRandomFace（探针 v1/v2/v3 实测确认）
        //    每个骰面(d4/.../d20/d100)独立设置；未设置的骰面保持正常。
        //    D20Die 继承 BasicDie 的 mapRandomFace，故攻击/豁免/检定/伤害/普通掷骰全覆盖。
        globalThis.__rngSocket = socket;                          // 给“掷骰面板”宏直接取用
        globalThis.__rngFaceRig = globalThis.__rngFaceRig || {};  // { "20": {action,value,lo,hi,p}, ... }
        if (!globalThis.__rngMapWrapped) {
            const DieClass = CONFIG.Dice.terms.d;                 // BasicDie；D20Die 是它的子类
            if (DieClass?.prototype && typeof DieClass.prototype.mapRandomFace === "function") {
                const origMap = DieClass.prototype.mapRandomFace;
                const ri = (lo, hi) => lo + Math.floor(Math.random() * (hi - lo + 1));
                const thrOf = (rig, f) => Math.max(2, Math.min(f, Math.round(rig.thr) || (Math.floor(f / 2) + 1)));
                const faceFor = (rig, f) => {
                    const half = Math.floor(f / 2);
                    switch (rig.action) {
                        case "fixed":    return Math.max(1, Math.min(f, rig.value));
                        case "range": {
                            let lo = Math.max(1, Math.min(f, rig.lo ?? 1));
                            let hi = Math.max(1, Math.min(f, rig.hi ?? f));
                            if (lo > hi) { const t = lo; lo = hi; hi = t; }
                            return ri(lo, hi);
                        }
                        case "biasLow": {
                            const thr = thrOf(rig, f);
                            return (Math.random() < rig.p) ? ri(1, thr - 1) : ri(thr, f);
                        }
                        case "biasHigh": {
                            const thr = thrOf(rig, f);
                            return (Math.random() < rig.p) ? ri(thr, f) : ri(1, thr - 1);
                        }
                        case "split": {
                            // 分段概率：pHigh% → [分界值, 骰面最大]；pLow% → [1, 分界值-1]；其余正常随机
                            const thr = thrOf(rig, f);
                            const ph = Math.max(0, Math.min(1, rig.pHigh ?? 0));
                            const pl = Math.max(0, Math.min(1, rig.pLow ?? 0));
                            const r = Math.random();
                            if (r < ph) return ri(thr, f);
                            if (r < ph + pl) return ri(1, thr - 1);
                            return null;
                        }
                        case "chance": {
                            // 概率命运：pCrit% → 大成功(骰面最大值)；pValue% → 设定的数值；其余正常随机
                            const pc = Math.max(0, Math.min(1, rig.pCrit ?? 0));
                            const pv = Math.max(0, Math.min(1, rig.pValue ?? 0));
                            const r = Math.random();
                            if (r < pc) return f;
                            if (r < pc + pv) return Math.max(1, Math.min(f, rig.value ?? f));
                            return null;
                        }
                        case "max":      return f;
                        case "min":      return 1;
                        default:         return null;
                    }
                };
                DieClass.prototype.mapRandomFace = function (...args) {
                    const rig = globalThis.__rngFaceRig ? globalThis.__rngFaceRig[this.faces] : null;
                    if (rig && rig.action !== "restore") {
                        const face = faceFor(rig, this.faces);
                        if (face != null) return face;
                    }
                    return origMap.apply(this, args);
                };
                globalThis.__rngMapWrapped = true;
                console.log("🎲 骰控-分骰面 已挂载到 mapRandomFace |", DieClass.name);
            } else {
                console.warn("🎲 骰控：未找到 mapRandomFace，分骰面未安装");
            }
        }
        socket.register("rng_apply", (data) => {
            if (!data || !data.faces) return false;
            globalThis.__rngFaceRig = globalThis.__rngFaceRig || {};
            if (!data.rig || data.rig.action === "restore") delete globalThis.__rngFaceRig[data.faces];
            else globalThis.__rngFaceRig[data.faces] = data.rig;
            return true;
        });
        socket.register("rng_restore_all", () => { globalThis.__rngFaceRig = {}; return true; });
        socket.register("rng_status", () => globalThis.__rngFaceRig || {});
        // 排查期：所有端都打印，方便确认 PL 是否真注册上了。确认无误后可把下一行包成 if(game.user?.isGM){...}
        console.log("🎲 骰控(socketlib/分骰面) 已注册 | 用户:", game.user?.name, "| isGM:", game.user?.isGM);
    } else {
        console.warn("⚠️ socketlib 未启用，酒馆小游戏与骰控模块已挂起。");
    }
}

// 传送门装置 · 常驻登记脚本  —— 放进 world-scripter（每次世界加载自动运行一次）
// 作用：① 定义 globalThis.PortalDevice.makePair（造一对相连传送门 Region）
//       ② 在 ready 时于 GM 端注册 socket 监听：玩家用物品时由 GM 端代为造门
//       ③ 可代玩家执行"把豁免失败目标传送到出口"（玩家无权限移动他人 token / 删他人效果）
(() => {
  const PORTAL_FLAG = "portalDevicePair";
  const SOCK_NS = "module.your-dm-toolkit";

  // 用 payload 里的 sceneId 定位场景；缺省回退到当前画布场景（向后兼容旧物品宏）
  const sceneOf = (p) => (p?.sceneId ? game.scenes.get(p.sceneId) : null) ?? canvas.scene;

  async function makePair(p) {
    const scene = sceneOf(p);
    if (!scene) { console.error("传送门装置 | 找不到目标场景"); return; }

    const poly = (tlp) => [{
      type: "polygon",
      points: [tlp.x, tlp.y, tlp.x + p.size, tlp.y, tlp.x + p.size, tlp.y + p.size, tlp.x, tlp.y + p.size],
      hole: false,
    }];

    // 清掉本装置上一对门（重新使用 = 换位）：Region + Drawing
    const old = scene.regions.filter((r) => r.getFlag("world", PORTAL_FLAG)?.deviceId === p.deviceId);
    if (old.length) await scene.deleteEmbeddedDocuments("Region", old.map((r) => r.id));
    const oldDraw = scene.drawings.filter((dw) => dw.getFlag("world", PORTAL_FLAG)?.deviceId === p.deviceId);
    if (oldDraw.length) await scene.deleteEmbeddedDocuments("Drawing", oldDraw.map((dw) => dw.id));

    // 由 GM 代执行"传送失败目标 + 清失败标记"。务必在【造门之前】做：
    //   门是双向的(踩出口→回入口)，若先造门再把目标搬到出口，会立刻触发传送把它弹回入口。
    //   门还没建时搬过去就不会触发；随后在它脚下把门建好，静止的它不会被再传。
    if (Array.isArray(p.warps)) {
      for (const w of p.warps) {
        try {
          const tokenDoc = scene.tokens.get(w.tokenId);
          if (!tokenDoc) continue;
          if (w.dest) await tokenDoc.update({ x: w.dest.x, y: w.dest.y }, { animate: false }); // GM 端移动，无弃用警告
          if (tokenDoc.actor && w.effectIds?.length) {
            const ids = tokenDoc.actor.effects.filter((e) => w.effectIds.includes(e.id)).map((e) => e.id);
            if (ids.length) await tokenDoc.actor.deleteEmbeddedDocuments("ActiveEffect", ids);
          }
        } catch (e) { console.error("传送门装置 | 代传送目标失败", e); }
      }
    }


    const mk = (role) => ({ world: { [PORTAL_FLAG]: { pairId: p.pairId, role, deviceId: p.deviceId } } });
    const [exitRegion] = await scene.createEmbeddedDocuments("Region", [{
      name: "传送门 出口", color: p.exitColor, shapes: poly(p.exit), flags: mk("exit"),
    }]);
    const [entryRegion] = await scene.createEmbeddedDocuments("Region", [{
      name: "传送门 入口", color: p.entryColor, shapes: poly(p.entry), flags: mk("entry"),
    }]);
    await entryRegion.createEmbeddedDocuments("RegionBehavior", [{ name: "传送", type: "teleportToken", system: { destination: exitRegion.uuid, choice: false } }]);
    await exitRegion.createEmbeddedDocuments("RegionBehavior", [{ name: "传送", type: "teleportToken", system: { destination: entryRegion.uuid, choice: false } }]);

    // 画布上的彩色视觉（Region 的 color 画布上不显示，靠 Drawing 上色）
    const RECT = foundry.data.ShapeData?.TYPES?.RECTANGLE ?? "r";
    const draw = (tlp, color, role) => ({
      x: tlp.x, y: tlp.y,
      shape: { type: RECT, width: p.size, height: p.size },
      fillType: 1, fillColor: color, fillAlpha: 0.5,
      strokeColor: color, strokeAlpha: 1, strokeWidth: 3,
      locked: true, interface: false,
      flags: { world: { [PORTAL_FLAG]: { pairId: p.pairId, role, deviceId: p.deviceId } } },
    });
    await scene.createEmbeddedDocuments("Drawing", [draw(p.entry, p.entryColor, "entry"), draw(p.exit, p.exitColor, "exit")]);

    // durationMs 后自动关闭
    const pid = p.pairId;
    setTimeout(async () => {
      try {
        const regs = scene.regions.filter((r) => r.getFlag("world", PORTAL_FLAG)?.pairId === pid);
        if (regs.length) await scene.deleteEmbeddedDocuments("Region", regs.map((r) => r.id));
        const drws = scene.drawings.filter((dw) => dw.getFlag("world", PORTAL_FLAG)?.pairId === pid);
        if (drws.length) await scene.deleteEmbeddedDocuments("Drawing", drws.map((dw) => dw.id));
      } catch (e) { console.error("传送门装置 | 自动关闭失败", e); }
    }, p.durationMs ?? 60000);

    return { entry: entryRegion.uuid, exit: exitRegion.uuid };
  }

  globalThis.PortalDevice = { makePair };

  // —— 关键修复：在 ready 时注册 GM 端 socket 监听（此时 game.socket / game.users 必定就绪）——
  function bindSocket() {
    if (globalThis.__portalDeviceSocketHooked) return;
    globalThis.__portalDeviceSocketHooked = true;
    game.socket.on(SOCK_NS, (data) => {
      try {
        if (data?.action !== "portalDeviceCreate") return;
        if (!game.user.isGM) return;
        // 多 GM 时只让主 GM 动手；取不到主 GM 时由本 GM 兜底，避免无人响应
        const primeGM = game.users.activeGM ?? game.users.find((u) => u.isGM && u.active);
        if (primeGM && primeGM.id !== game.user.id) return;
        globalThis.PortalDevice.makePair(data.payload);
      } catch (e) { console.error("传送门装置 | socket 处理出错", e); }
    });
    console.log("传送门装置 | GM 端 socket 监听已注册");
  }
  if (game.ready) bindSocket(); else Hooks.once("ready", bindSocket);

  console.log("传送门装置 | 常驻脚本已加载");
})();

// 附身符 — 常驻通道（放进 world-scripter）。模式照「传送门装置」：玩家端 emit → GM 端执行。
(() => {
  const NS = "module.your-dm-toolkit";   // 与传送门/YGM 同一条合法频道（world.* 不会被 Foundry 广播）
  const SCOPE = "world";
  const ORIG = "possessionOrigOwnership";
  const POSSESSED = "possessed";        // 目标 token 标记：被附身中
  const POSSESSOR = "possessor";        // 记录附身者（本体）tokenId
  const SELF_FLAG = "possessSelf";      // 本体「出窍」effect 的 world flag
  const SAVE_DC = 15;

  const ownerLvl = () => (CONST?.DOCUMENT_OWNERSHIP_LEVELS?.OWNER ?? 3);

  async function confirmDialog(title, content) {
    try {
      return await foundry.applications.api.DialogV2.confirm({ window: { title }, content });
    } catch (e) {
      return await new Promise((res) => {
        new Dialog({ title, content, buttons: {
          yes: { label: "同意", callback: () => res(true) },
          no: { label: "拒绝", callback: () => res(false) }
        }, default: "no", close: () => res(false) }).render(true);
      });
    }
  }

  function getTokenDoc(sceneId, tokenId) {
    const scene = game.scenes.get(sceneId) ?? canvas.scene;
    return scene?.tokens?.get(tokenId) ?? null;
  }

  // unlinked（非链接）token 改 tokenDoc.actor 的 ownership 不生效——要改它背后的基础世界 actor，
  // 投影 token 会继承到玩家的 OWNER 权限，玩家才能控制；linked token 则直接用其 actor。
  function ownerActorOf(tokenDoc) {
    const a = tokenDoc?.actor;
    if (a?.isToken) return game.actors.get(tokenDoc.actorId) ?? a;
    return a;
  }

  async function doGrant({ targetTokenId, playerUserId, sceneId }) {
    if (!game.user.isGM) return;
    const tokenDoc = getTokenDoc(sceneId, targetTokenId);
    const player = game.users.get(playerUserId);
    if (!tokenDoc?.actor || !player) return;
    const ok = await confirmDialog("附身请求",
      `<p>玩家 <b>${player.name}</b> 请求附身 <b>${tokenDoc.name}</b>。</p><p>同意将其控制权临时转交给该玩家？</p>`);
    if (!ok) { ui.notifications.info(`已拒绝对 ${tokenDoc.name} 的附身`); return; }
    const oa = ownerActorOf(tokenDoc);
    if (!oa) { console.warn("附身grant | 取不到可写 actor"); return; }
    const orig = foundry.utils.deepClone(oa.ownership ?? {});
    await tokenDoc.setFlag(SCOPE, ORIG, orig);
    const newOwn = foundry.utils.deepClone(oa.ownership ?? {});
    newOwn[playerUserId] = ownerLvl();
    await oa.update({ ownership: newOwn });
    console.log("附身grant诊断 | 玩家:", player.name, "(", playerUserId, ") | token:", tokenDoc.name,
      "| unlinked:", !!tokenDoc.actor?.isToken, "| 写入 actor:", oa.name,
      "| 更新后该玩家权限:", oa.ownership?.[playerUserId], "(3=OWNER 才算成功)");
    ui.notifications.info(`${player.name} 已接管 ${tokenDoc.name}`);
  }

  async function doRevoke({ targetTokenId, sceneId, playerUserId }) {
    if (!game.user.isGM) return;
    const tokenDoc = getTokenDoc(sceneId, targetTokenId);
    if (!tokenDoc?.actor) return;
    const oa = ownerActorOf(tokenDoc);
    if (!oa) return;
    const orig = tokenDoc.getFlag(SCOPE, ORIG) ?? {};
    // 关键：actor.update 的 ownership 是【深合并】，写回旧对象不会删掉 grant 期间新增的玩家 key。
    // 要真正收回，必须对该玩家 key 用 Foundry 的删除语法 "-=ID":null（或还原其 grant 前的旧值）。
    const upd = {};
    if (playerUserId) {
      if (playerUserId in orig) upd[playerUserId] = orig[playerUserId];   // grant 前本就有权限 → 还原旧值
      else upd[`-=${playerUserId}`] = null;                               // grant 新增 → 删除该 key
    }
    if (Object.keys(upd).length) await oa.update({ ownership: upd });
    await tokenDoc.unsetFlag(SCOPE, ORIG);
    // 诊断：确认恢复后该玩家权限（应为 undefined 或 <3）
    if (playerUserId && oa) console.log("附身revoke诊断 | token:", tokenDoc.name, "| 写入 actor:", oa.name, "| 恢复后该玩家权限:", oa.ownership?.[playerUserId], "(应为 undefined 或 <3 才算收回)");
    // 改 ownership 不会自动踢开玩家当前正选中的 token——发 release 信号让控制它的客户端主动放手
    try { game.socket.emit(NS, { action: "possessRelease", tokenId: targetTokenId }); } catch (e) {}
    try { canvas.tokens?.get(targetTokenId)?.release(); } catch (e) {}
    ui.notifications.info(`已收回 ${tokenDoc.name} 的控制权`);
  }

  // 附身结束的完整收尾——必须在 GM 端跑（改 ownership / 删目标标记 / 代目标豁免都需 GM 权限）。
  // onDelete 可能在玩家端触发，故经此通道委派给 GM；带去重，避免重复弹察觉豁免。
  async function doCleanup({ targetTokenId, sceneId, playerUserId, selfName }) {
    if (!game.user.isGM) return;
    const scene = game.scenes.get(sceneId) ?? canvas.scene;
    const tgtDoc = scene?.tokens?.get(targetTokenId);
    const tgtActor = tgtDoc?.actor ?? null;
    const stillPossessed = tgtActor?.effects?.find((e) => e.getFlag(SCOPE, POSSESSED));
    // 1) 收回控制权（幂等，可安全重复）
    await doRevoke({ targetTokenId, sceneId, playerUserId });
    if (!tgtActor || !stillPossessed) return;   // 已收尾过 → 不再重复删标记/弹豁免
    // 2) 删「被附身」标记
    try { const ids = tgtActor.effects.filter((e) => e.getFlag(SCOPE, POSSESSED)).map((e) => e.id); if (ids.length) await tgtActor.deleteEmbeddedDocuments("ActiveEffect", ids); } catch (e) {}
    // 3) 退出察觉：感知豁免 DC15 + 结束聊天卡
    let total = 0;
    try { const r = await tgtActor.rollSavingThrow({ ability: "wis" }, {}, {}); total = (Array.isArray(r) ? r[0] : r)?.total ?? 0; }
    catch (e) { try { const r = await tgtActor.rollAbilitySave?.("wis"); total = r?.total ?? 0; } catch (e2) {} }
    const aware = total >= SAVE_DC;
    ChatMessage.create({ content: `<p>附身结束，<b>${selfName ?? "附身者"}</b> 的意识弹回本体。<b>${tgtActor.name}</b> 退出察觉（感知豁免 ${total}）：${aware ? "<b>察觉</b>到自己方才被人操控。" : "毫无察觉，对刚才一无所知。"}</p>` });
  }

  globalThis.PossessionCharm = {
    grant: (p) => game.user.isGM ? doGrant(p) : game.socket.emit(NS, { action: "possessGrant", ...p }),
    revoke: (p) => game.user.isGM ? doRevoke(p) : game.socket.emit(NS, { action: "possessRevoke", ...p }),
    cleanup: (p) => game.user.isGM ? doCleanup(p) : game.socket.emit(NS, { action: "possessCleanup", ...p }),
  };

  game.socket.on(NS, (data) => {
    // release 信号所有端都处理（含被附身的那个玩家端），必须放在 GM 守卫之前
    if (data?.action === "possessRelease") { try { canvas.tokens?.get(data.tokenId)?.release(); } catch (e) {} return; }
    if (!game.user.isGM) return;
    if (data?.action !== "possessGrant" && data?.action !== "possessRevoke" && data?.action !== "possessCleanup") return; // 共用频道，只认附身专属动作
    const primeGM = game.users.activeGM ?? game.users.find((u) => u.isGM && u.active);
    if (primeGM && primeGM.id !== game.user.id) return;   // 多 GM 只让主 GM 处理，避免重复弹框
    if (data.action === "possessGrant") doGrant(data);
    else if (data.action === "possessRevoke") doRevoke(data);
    else if (data.action === "possessCleanup") doCleanup(data);
  });

  // 受伤挣脱：被附身宿主真实掉血 → 感知豁免 DC15，过则结束附身（删本体「出窍」effect → 触发其 onDelete 收尾）
  // 用 preUpdate 取「更新前」的真实旧 HP——不依赖 opts 的伤害来源路径，AlwaysHP/midi/手动改血都适用；
  // 污染计数器等「不含 HP」的杂改会被 updateActor 首条 newHp===undefined 挡掉，不会误触发。
  const _possHpBefore = new Map();
  Hooks.on("preUpdateActor", (actor, change) => {
    const nh = foundry.utils.getProperty(change, "system.attributes.hp.value");
    if (nh === undefined) return;
    _possHpBefore.set(actor.id, actor.system?.attributes?.hp?.value ?? nh);
  });
  Hooks.on("updateActor", async (actor, change, opts, userId) => {
    if (!game.user.isGM) return;
    const newHp = foundry.utils.getProperty(change, "system.attributes.hp.value");
    if (newHp === undefined) return;                       // 本次 update 不含 HP（如改 ownership/污染）→ 不是受创
    const oldHp = _possHpBefore.get(actor.id); _possHpBefore.delete(actor.id);
    if (oldHp === undefined || newHp >= oldHp) return;     // 没掉血
    const possessedEff = actor.effects?.find((e) => e.getFlag(SCOPE, POSSESSED));
    if (!possessedEff) return;
    let total = 0;
    try {
      const r = await actor.rollSavingThrow({ ability: "wis" }, {}, {});
      total = (Array.isArray(r) ? r[0] : r)?.total ?? 0;
    } catch (e) { try { const r = await actor.rollAbilitySave?.("wis"); total = r?.total ?? 0; } catch (e2) {} }
    if (total >= SAVE_DC) {
      ChatMessage.create({ content: `<p><b>${actor.name}</b> 受创后挣脱了附身（感知豁免 ${total} ≥ ${SAVE_DC}）！</p>` });
      const possessorId = possessedEff.getFlag(SCOPE, POSSESSOR);
      const possessorTok = canvas.tokens?.placeables?.find((t) => t.id === possessorId);
      const selfEff = possessorTok?.actor?.effects?.find((e) => e.getFlag(SCOPE, SELF_FLAG));
      if (selfEff) { try { await selfEff.delete(); } catch (e) {} }   // 删出窍 effect → 其 onDelete 收回控制权+弹回+察觉
      else { // 兜底：直接收回 + 清标记
        await doRevoke({ targetTokenId: canvas.tokens.placeables.find(t => t.actor?.id === actor.id)?.id, sceneId: canvas.scene.id });
        try { await possessedEff.delete(); } catch (e) {}
      }
    } else {
      ChatMessage.create({ content: `<p><b>${actor.name}</b> 试图挣脱附身，但失败了（感知豁免 ${total} < ${SAVE_DC}）。</p>` });
    }
  });

  console.log("附身符 | 常驻通道已就绪");
})();

/* ===========================================================
   魔法荒野厨房 — UI 按钮（免导入·强制接管版）
   世界里没有该宏就去合集包(compendium)里找，读出命令体当普通 JS 执行，
   不导入世界、也不需要"使用脚本宏"权限。
   前提：① 合集包里有同名宏【魔法荒野厨房  Wilderness Kitchen】（中英文之间两个空格）；
         ② 该合集包对玩家可见（右键合集包→配置可见性）。
   =========================================================== */
(() => {
  const WK_MACRO_NAME = "魔法荒野厨房  Wilderness Kitchen";

  // 清掉可能残留的旧轮询器 / 旧按钮，强制由本版接管
  if (globalThis.wkKitchenBtnPoller) { try { clearInterval(globalThis.wkKitchenBtnPoller); } catch (e) {} }
  document.getElementById("wk-kitchen-btn")?.remove();

  // 世界 -> 各 Macro 合集包按名查找；找不到则把所有宏名打到控制台便于核对
  async function wkFetchKitchenMacro() {
    let m = game.macros.getName(WK_MACRO_NAME);
    if (m) return m;
    const seen = [];
    for (const pack of game.packs) {
      if (pack.documentName !== "Macro") continue;
      try { await pack.getIndex(); } catch (e) { continue; }
      for (const e of pack.index) seen.push(pack.collection + " :: " + e.name);
      const entry = pack.index.getName ? pack.index.getName(WK_MACRO_NAME)
                                       : pack.index.find(e => e.name === WK_MACRO_NAME);
      if (entry) { try { return await pack.getDocument(entry._id); } catch (e) {} }
    }
    console.warn("🍲 未找到目标宏。当前所有【宏类】合集里的宏名（逐字核对，注意中英文间两个空格）：", seen);
    return null;
  }

  // 直接把宏命令体当普通异步函数跑（不调用 Macro#execute，绕开脚本宏权限）
  globalThis.wkRunKitchen = async function () {
    const m = await wkFetchKitchenMacro();
    if (!m) { ui.notifications.warn("找不到宏【" + WK_MACRO_NAME + "】。已把所有合集里的宏名打到 F12，请核对名字/空格，或确认合集包对你可见。"); return; }
    try {
      const AsyncFunction = foundry.utils.AsyncFunction ?? Object.getPrototypeOf(async function () {}).constructor;
      const speaker = ChatMessage.getSpeaker();
      const character = game.user.character ?? null;
      const token = canvas?.tokens?.controlled?.[0] ?? null;
      const actor = token?.actor ?? character ?? null;
      const fn = new AsyncFunction("speaker", "actor", "token", "character", "scope", "event", m.command);
      await fn.call(m, speaker, actor, token, character, {}, {});
    } catch (err) {
      console.error("魔法荒野厨房执行出错：", err);
      ui.notifications.error("厨房宏执行出错，详见 F12 控制台。");
    }
  };

  // 注入左侧工具栏按钮（锚点沿用冒险者履历同款）
  globalThis.wkKitchenBtnPoller = setInterval(() => {
    const $anchor = $('button.control.ui-control.layer.icon.fa-solid.fa-bookmark');
    if ($anchor.length > 0 && $('#wk-kitchen-btn').length === 0) {
      const btn = $('<button id="wk-kitchen-btn" class="control ui-control layer icon fa-solid fa-utensils" title="魔法荒野厨房" style="color:#e0a96d; margin-top:5px;"></button>');
      btn.on('click', () => globalThis.wkRunKitchen());
      btn.insertAfter($anchor);
    }
  }, 1500);

  console.log("🍲 魔法荒野厨房 UI 按钮（免导入·强制接管）已启动");
})();

/* =====================================================================
 *  知音 · 和鸣 —— 触发型钩子（赋格 + 强音翻倍）
 *  用法：把本段整体粘进 world-scripter 的脚本里（保存后重载世界一次）。
 *  作用：
 *   - 赋格 Fugue：带「赋格」效果的盟友命中一个失谐目标(flags.world.zhiyinDiscord)时，
 *     吟游诗人(效果来源的持有者)回复 = 其魅力调整值 的生命。
 *   - 强音和弦 翻倍：带「强音和弦」效果的盟友对失谐目标造成伤害时，
 *     追加一份 = 诗人等级 的雷鸣伤害（基础那份由卡面自动加，这一份即"对失谐翻倍"）。
 *  仅 GM 端执行，避免重复结算。全程 try/catch，出错只在控制台告警、不影响其它。
 * ===================================================================== */
Hooks.on("midi-qol.RollComplete", async (workflow) => {
  try {
    if (!game.user.isGM) return;
    const attacker = workflow?.actor;
    if (!attacker) return;
    const eff = attacker.appliedEffects ?? [];
    const cres  = eff.find(e => (e.name || "").includes("强音和弦"));
    const fugue = eff.find(e => (e.name || "").includes("赋格"));
    if (!cres && !fugue) return;

    // 反查吟游诗人（效果来源 = 知音 的活动/物品）
    const bardOf = async (e) => {
      try { const o = await fromUuid(e.origin);
            return o?.actor ?? o?.item?.actor ?? o?.parent?.actor ?? o?.parent ?? null; }
      catch (_) { return null; }
    };

    const hits = workflow.hitTargets ?? workflow.targets ?? new Set();
    for (const t of hits) {
      const ta = t?.actor; if (!ta) continue;
      const discord = (ta.appliedEffects ?? []).some(x => x.flags?.world?.zhiyinDiscord);
      if (!discord) continue;

      // 强音翻倍：读出「强音和弦」实际追加的雷鸣数值，再加等量（真翻倍，不管基础7还是即兴12）
      if (cres) {
        let amt = 0;
        try {
          const ch = (cres.changes || []).find(c => /All-Damage/i.test(c.key) && /thunder/i.test(String(c.value)));
          if (ch) amt = parseInt(String(ch.value).match(/-?\d+/)?.[0] ?? "0", 10) || 0;
        } catch (_) {}
        if (amt > 0) {
          try { await ta.applyDamage([{ value: amt, type: "thunder" }]); }
          catch (_) { await ta.applyDamage(amt); }
        }
      }
      // 赋格：吟游诗人回 = 魅力调整 的血
      if (fugue) {
        const bard = await bardOf(fugue);
        const cha = bard?.system?.abilities?.cha?.mod ?? 0;
        if (bard && cha > 0) {
          try { await bard.applyDamage([{ value: cha, type: "healing" }]); }
          catch (_) { await bard.applyDamage(-cha); }
        }
      }
    }
  } catch (e) { console.warn("知音 world-scripter 钩子出错（不影响其它）：", e); }
});

/* =====================================================================
 *  知音 · 和鸣 —— 不谐之债 战斗结束清算
 *  战斗结束时，把每个角色身上的【失谐·债】按 层数 × 诗人等级 结算为心灵伤害，
 *  然后清零并移除这些效果（含其法术豁免 DC −1 的减值）。
 *  （战斗外透支时，物品宏已当场结算，不依赖本钩子。）
 * ===================================================================== */
Hooks.on("deleteCombat", async (combat) => {
  try {
    if (!game.user.isGM) return;
    for (const c of combat.combatants) {
      const a = c.actor; if (!a) continue;
      const debts = (a.appliedEffects ?? []).filter(e => e.flags?.world?.zhiyinDebt || e.name === "失谐·债 Dissonant Debt");
      const n = debts.length; if (!n) continue;
      const lvl = a.classes?.bard?.system?.levels
               ?? a.itemTypes?.class?.find?.(x => (x.identifier||x.system?.identifier)==="bard")?.system?.levels ?? 0;
      const dmg = n * lvl;
      if (dmg > 0) { try { await a.applyDamage([{ value: dmg, type: "psychic" }]); } catch (_) { await a.applyDamage(dmg); } }
      await a.deleteEmbeddedDocuments("ActiveEffect", debts.map(e => e.id));
      ChatMessage.create({ speaker: { alias: "知音" },
        content: `<b>不谐之债 · 清算</b><br>${a.name} 背负 ${n} 层失谐·债，终止式向内落地，结算 <b>${dmg}</b> 点心灵伤害，债清。` });
    }
  } catch (e) { console.warn("知音 债务清算钩子出错：", e); }
});

/* =====================================================================
 *  知音 · 和鸣 —— 滑音 GM 端 socket（给盟友挂/卸临时反应特性）
 *  物品宏以玩家身份 emit；这里在 GM 端接收并执行（玩家无权写他人角色）。
 *  仅"首位在线 GM"执行，避免多 GM 重复创建。带同名去重。
 * ===================================================================== */
Hooks.once("ready", () => {
  try {
    game.socket.on("module.world-scripter", async (msg) => {
      try {
        if (!game.user.isGM) return;
        const firstGM = game.users.find(u => u.isGM && u.active);
        if (game.user !== firstGM) return;            // 只让首位在线 GM 处理
        if (!msg || msg.scope !== "zhiyin") return;
        const o = await fromUuid(msg.tokenUuid); const a = o?.actor ?? o; if (!a) return;
        if (msg.action === "grantItem") {
          if (a.items.some(i => i.name === msg.itemData?.name)) return;   // 去重
          await a.createEmbeddedDocuments("Item", [msg.itemData]);
        } else if (msg.action === "revertItem") {
          const ids = a.items.filter(i => i.name === msg.itemName).map(i => i.id);
          if (ids.length) await a.deleteEmbeddedDocuments("Item", ids);
        }
      } catch (e) { console.warn("知音 socket 处理出错：", e); }
    });
    console.log("知音 | world-scripter GM socket 已就绪");
  } catch (e) { console.warn("知音 socket 注册失败：", e); }
});


