// 通用 GM 代办 YGM · 常驻登记脚本 —— 放进 world-scripter（与传送门脚本并列，各自独立）
// 作用：玩家宏需要对【自己不拥有的 token】做特权操作（移动、加状态、加/删效果）时，
//       打包成 ops 交给本脚本，由 GM 端统一执行，避免 "lacks permission" 报错。
// 用法（在任意玩家宏里）：
//   await globalThis.YGM.request({ sceneId: canvas.scene.id, ops: [
//     { tokenId, move:{x,y,animate}, addStatuses:["prone"], damage:[{value,type}], deleteFlag:{scope:"world",key:"viMark"}, createEffects:[...], deleteEffectIds:[...] }
//   ]});
(() => {
  const SOCK_NS = "module.your-dm-toolkit"; // 与传送门同频道；本模块 manifest 已开 "socket": true

  async function apply({ sceneId, ops } = {}) {
    const scene = (sceneId ? game.scenes.get(sceneId) : null) ?? canvas.scene;
    if (!scene || !Array.isArray(ops)) return;
    for (const op of ops) {
      try {
        const td = scene.tokens.get(op.tokenId);
        if (!td) continue;
        const actor = td.actor;
        if (op.move) {
          await td.update({ x: op.move.x, y: op.move.y }, { animate: op.move.animate ?? true });
        }
        if (actor && Array.isArray(op.addStatuses)) {
          for (const st of op.addStatuses) {
            try { await actor.toggleStatusEffect(st, { active: true }); }
            catch (e) { console.error("YGM | toggleStatus 失败", st, e); }
          }
        }
        if (actor && Array.isArray(op.createEffects) && op.createEffects.length) {
          await actor.createEmbeddedDocuments("ActiveEffect", op.createEffects);
        }
        if (actor && Array.isArray(op.damage) && op.damage.length) {
          await actor.applyDamage(op.damage);   // 例: [{value:8,type:"force"}]；type:"healing" 即治疗（字典 §747）
        }
        if (actor && op.deleteFlag) {
          const ids = actor.effects
            .filter((e) => e.getFlag(op.deleteFlag.scope, op.deleteFlag.key) !== undefined)
            .map((e) => e.id);
          if (ids.length) await actor.deleteEmbeddedDocuments("ActiveEffect", ids);
        }
        if (actor && Array.isArray(op.deleteEffectIds) && op.deleteEffectIds.length) {
          const ids = op.deleteEffectIds.filter((id) => actor.effects.get(id));
          if (ids.length) await actor.deleteEmbeddedDocuments("ActiveEffect", ids);
        }
      } catch (e) { console.error("YGM | op 执行失败", op, e); }
    }
  }

  globalThis.YGM = {
    apply,
    // 玩家端调用：是 GM 就直接做，否则委托 GM
    request(data) {
      if (game.user.isGM) return apply(data);
      game.socket.emit(SOCK_NS, { action: "ygmApply", ...data });
    },
  };

  function bind() {
    if (globalThis.__ygmSocketHooked) return;
    globalThis.__ygmSocketHooked = true;
    game.socket.on(SOCK_NS, (msg) => {
      try {
        if (msg?.action !== "ygmApply") return;        // 只处理本动作，与传送门监听互不干扰
        if (!game.user.isGM) return;
        const primeGM = game.users.activeGM ?? game.users.find((u) => u.isGM && u.active);
        if (primeGM && primeGM.id !== game.user.id) return; // 多 GM 只让主 GM 动手
        apply(msg);
      } catch (e) { console.error("YGM | socket 处理出错", e); }
    });
    console.log("YGM | GM 端通用代办监听已注册");
  }
  if (game.ready) bind(); else Hooks.once("ready", bind);
})();

// 【全域双保险机制】强制引爆加载器
// ==========================================
if (game.ready) {
    initializeWorldScripts();
} else {
    Hooks.once("ready", initializeWorldScripts);
}

globalThis.__yourReady = true;
